class ReflexVacuumAgent:
    def __init__(self):
        self.location = 'A'

    def act(self, percept: dict) -> str:
        location = percept['location']
        is_dirty = percept['is_dirty']

        if is_dirty:
            return 'SUCK_DIRT'
        elif location == 'A':
            return 'MOVE_RIGHT'
        elif location == 'B':
            return 'MOVE_LEFT'

agent = ReflexVacuumAgent()
action = agent.act({'location': 'A', 'is_dirty': True})
print(f'Selected action: {action}')
